function displayRegion(region: Intelligence["region"] | (typeof regionOptions)[number], language: Language) { return regionLocalized[language][region as Intelligence["region"]]; }
function displaySubject(subject: BusinessSubject | (typeof subjectOptions)[number], language: Language) { return subjectLocalized[language][subject as BusinessSubject]; }
function displayScenario(scenario: BusinessScenario | (typeof scenarioOptions)[number], language: Language) { return scenarioLocalized[language][scenario as BusinessScenario]; }
function displayStatus(status: Intelligence["status"], language: Language) { if (language === "en") return status === "已核验" ? "Verified" : "Review"; if (language === "id") return status === "已核验" ? "Terverifikasi" : "Tinjau"; if (language === "vi") return status === "已核验" ? "Đã xác minh" : "Cần xem"; if (language === "pt") return status === "已核验" ? "Verificado" : "Revisão"; return status; }
function displayDate(date: string, language: Language = "zh") { return language === "zh" ? date.slice(5).replace("-", ".") : new Intl.DateTimeFormat(dateLocales[language], { month: "short", day: "numeric", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`)); }
function monthLabel(month: string, language: Language = "zh") { return language === "zh" ? `${month.slice(0, 4)} 年 ${month.slice(5)} 月` : new Intl.DateTimeFormat(dateLocales[language], { month: "short", year: "numeric", timeZone: "UTC" }).format(new Date(`${month}-01T00:00:00Z`)); }
function displayCompany(company: string, language: Language) {
  if (language === "zh") return company;
  return company.replaceAll("美团", "Meituan").replaceAll("京东秒送（达达）", "JD Instant Delivery (Dada)").replaceAll("钛牛数码", "Tainiu Digital").replaceAll("有赞零售", "Youzan Retail").replaceAll("京东", "JD.com").replaceAll("阿里巴巴", "Alibaba").replaceAll("淘宝闪购", "Taobao Instant").replaceAll("盒马", "Freshippo").replaceAll("千问", "Qwen").replaceAll("京东外卖", "JD Food").replaceAll("苏州交管", "Suzhou Traffic Police").replaceAll("北京市商务局等 4 部门", "Beijing commerce authorities").replaceAll("重庆市气象台", "Chongqing Meteorological Service").replaceAll("重庆市应急管理局", "Chongqing Emergency Management Bureau").replaceAll("印尼通信与数字部", "Indonesia Ministry of Communication and Digital Affairs").replaceAll("沙特公共交通总局", "Saudi Public Transport Authority").replaceAll("巴西 MDIC", "Brazil MDIC").replaceAll("新加坡人力部", "Singapore Ministry of Manpower").replaceAll("外卖 / 快递平台与站点", "Food-delivery / courier platforms and stations").replaceAll("武汉公安", "Wuhan Police").replaceAll("商圈", "business districts").replaceAll("外卖平台", "food-delivery platforms");
}
function displayMarket(market: string, language: Language) {
  if (language === "zh") return market;
  return market.replaceAll("中国大陆", "Mainland China").replaceAll("全国", "Nationwide").replaceAll("全球", "Global").replaceAll("拉美可关注", "watch in Latin America").replaceAll("中国台湾", "Taiwan").replaceAll("东南亚", "Southeast Asia").replaceAll("重庆", "Chongqing").replaceAll("苏州", "Suzhou").replaceAll("北京", "Beijing").replaceAll("上海", "Shanghai").replaceAll("宁波", "Ningbo").replaceAll("华东", "East China").replaceAll("新加坡", "Singapore").replaceAll("墨西哥", "Mexico").replaceAll("哥伦比亚", "Colombia").replaceAll("阿根廷", "Argentina").replaceAll("巴西", "Brazil").replaceAll("圣保罗", "São Paulo").replaceAll("沙特", "Saudi Arabia").replaceAll("阿联酋", "UAE").replaceAll("埃及", "Egypt").replaceAll("海湾地区", "Gulf region").replaceAll("印度尼西亚", "Indonesia").replaceAll("马来西亚", "Malaysia").replaceAll("赣州", "Ganzhou").replaceAll("武汉", "Wuhan").replaceAll("全国", "Nationwide");
}
function displayItem(item: Intelligence, language: Language) {
  const copy = language === "zh" ? undefined : englishItemCopies[item.id];
  return { title: copy?.title ?? item.titleEn ?? item.title, summary: copy?.summary ?? item.summaryEn ?? item.summary, implication: copy?.implication ?? item.implicationEn ?? item.implication, company: displayCompany(item.company, language), market: displayMarket(item.market, language), sourceLabel: item.sourceLabel };
}

